setup:
MUTATE {
 CREATE CONCEPT ?a { TYPE "Person" NAME "Ada" }
 CREATE CONCEPT ?work { TYPE "Person" NAME "work" }
 CREATE CONCEPT ?travel { TYPE "Person" NAME "travel" }
 ENSURE PROPOSITION ?home (?a, "position", "home")
 ENSURE PROPOSITION ?office (?a, "position", "office")
 ENSURE PROPOSITION ?tea (?a, "likes", "tea")
 ENSURE PROPOSITION ?coffee (?a, "likes", "coffee")
 ENSURE PROPOSITION ?w (?a, "scoped", "work")
 ENSURE PROPOSITION ?t (?a, "scoped", "travel")
 ENSURE PROPOSITION ?old (?a, "temporal", "old")
 ENSURE PROPOSITION ?new (?a, "temporal", "new")
 CREATE ASSERTION ?a1 { SET FIELDS { proposition: ?home, asserted_by: ?a, stance: "support", mode: "stated", confidence: 0.9 } }
 CREATE ASSERTION ?a2 { SET FIELDS { proposition: ?office, asserted_by: ?a, stance: "support", mode: "stated", confidence: 0.9 } }
 CREATE ASSERTION ?a3 { SET FIELDS { proposition: ?tea, asserted_by: ?a, stance: "support", mode: "stated", confidence: 0.9 } }
 CREATE ASSERTION ?a4 { SET FIELDS { proposition: ?coffee, asserted_by: ?a, stance: "support", mode: "stated", confidence: 0.9 } }
 CREATE ASSERTION ?a5 { SET FIELDS { proposition: ?w, asserted_by: ?a, stance: "support", mode: "stated", confidence: 0.9, context_refs: [?work] } }
 CREATE ASSERTION ?a6 { SET FIELDS { proposition: ?t, asserted_by: ?a, stance: "support", mode: "stated", confidence: 0.9, context_refs: [?travel] } }
 CREATE ASSERTION ?a7 { SET FIELDS { proposition: ?old, asserted_by: ?a, stance: "support", mode: "stated", confidence: 0.9, valid_time: { from: "2026-09-01T00:00:00.000Z", until: "2026-09-07T00:00:00.000Z" } } }
 CREATE ASSERTION ?a8 { SET FIELDS { proposition: ?new, asserted_by: ?a, stance: "support", mode: "stated", confidence: 0.9, valid_time: { from: "2026-09-07T00:00:00.000Z" } } }
}
